const usedPrivateIPs = `-- name: UsedPrivateIPs :many
SELECT private_ip FROM servers WHERE private_ip <> ''
`

func (q *Queries) UsedPrivateIPs(ctx context.Context) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, usedPrivateIPs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var private_ip string
		if err := rows.Scan(&private_ip); err != nil {
			return nil, err
		}
		items = append(items, private_ip)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const webServicesOnServer = `-- name: WebServicesOnServer :many
SELECT s.name, e.name AS env, p.name AS project FROM services s JOIN environments e ON e.id = s.environment_id JOIN projects p ON p.id = e.project_id
WHERE e.server_id = ? AND s.kind = 'web' AND s.deleted_at IS NULL AND e.deleted_at IS NULL AND p.deleted_at IS NULL ORDER BY p.name, e.name, s.name
`

type WebServicesOnServerRow struct {
	Name    string
	Env     string
	Project string
}

func (q *Queries) WebServicesOnServer(ctx context.Context, serverID string) ([]WebServicesOnServerRow, error) {
	rows, err := q.db.QueryContext(ctx, webServicesOnServer, serverID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WebServicesOnServerRow
	for rows.Next() {
		var i WebServicesOnServerRow
		if err := rows.Scan(&i.Name, &i.Env, &i.Project); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
